MIME_MAP = {
    ".jpg":  "image/jpeg",
    ".jpeg": "image/jpeg",
    ".png":  "image/png",
    ".webp": "image/webp",
    ".pdf":  "application/pdf",
}


def get_extension(path: str) -> str:
    """Return the file extension from a local path or URL."""
    return pathlib.Path(path.split("?")[0]).suffix.lower()


def get_mime_type(path: str) -> str:
    """Guess the MIME type from the extension."""
    ext = get_extension(path)
    return MIME_MAP.get(ext, mimetypes.guess_type(path)[0] or "application/octet-stream")


def load_bytes(path: str) -> bytes:
    """Load bytes from a URL or local file."""
    if path.startswith("http"):
        response = requests.get(path, timeout=60)
        response.raise_for_status()
        return response.content
    return pathlib.Path(path).read_bytes()


def detect_modality(path: str) -> str:
    """Simple modality detection."""
    ext = get_extension(path)
    if ext in [".jpg", ".jpeg", ".png", ".webp"]:
        return "image"
    if ext == ".pdf":
        return "document"
    return "unknown"

def extract_pdf_text(path: str) -> str:
    """Extract text from a local or remote PDF."""
    pdf_bytes = load_bytes(path)
    doc = fitz.open(stream=pdf_bytes, filetype="pdf")

    pages = []
    for page_number, page in enumerate(doc, start=1):
        text = page.get_text("text").strip()
        if text:
            pages.append(f"Page {page_number}\n{text}")

    return "\n\n".join(pages)


def chunk_text(text: str, chunk_size: int = 1200, overlap: int = 200) -> list[str]:
    """Split long text into overlapping chunks."""
    chunks = []
    start = 0

    while start < len(text):
        end = start + chunk_size
        chunk = text[start:end].strip()
        if chunk:
            chunks.append(chunk)
        start = end - overlap

    return chunks


def caption_image(path: str) -> str:
    """Create a short searchable caption for an image."""
    image_bytes = load_bytes(path)
    mime = get_mime_type(path)

    response = client.models.generate_content(
        model=GEMINI_TEXT_MODEL,
        contents=[
            "Describe this image for a RAG system. Be factual and concise.",
            types.Part.from_bytes(data=image_bytes, mime_type=mime),
        ],
    )

    return response.text.strip()

chroma_client = chromadb.PersistentClient(
    path="./chroma_db",
    settings=Settings(anonymized_telemetry=False),
)

if RESET_COLLECTION:
    try:
        chroma_client.delete_collection(COLLECTION_NAME)
    except Exception:
        pass

collection = chroma_client.get_or_create_collection(
    name=COLLECTION_NAME,
    metadata={"hnsw:space": "cosine"},
)

print("Collection ready:", COLLECTION_NAME)

def remove(doc_id: str):
    """Remove all chunks belonging to one original document."""
    collection.delete(where={"parent_id": doc_id})
    print(f"✅ Removed {doc_id}")


def update(doc_id: str, path: str, metadata: dict | None = None):
    """Simple update: delete old chunks, then ingest the new file."""
    remove(doc_id)
    return ingest(path=path, doc_id=doc_id, metadata=metadata)
